function demoWorld(){const w=E.createWorld('Borough','river',321);const street=(x,y,wide=false)=>{const t=w.tiles[y*48+x];if(t.ground==='land'){t.type='road';t.tree=false;t.roadWidth=wide?2:1}};for(let y of [12,18,24,30,36])for(let x=0;x<32;x++)street(x,y,y===24);for(let x of [8,14,20,26,31])for(let y=9;y<39;y++)street(x,y,x===20);for(let y=10;y<38;y++)for(let x=6;x<31;x++){const t=w.tiles[y*48+x],h=(x*17+y*31)%13;if(t.ground==='water'||t.type||h===0)continue;if(E.neighbors(y*48+x).some(i=>w.tiles[i].type==='road')||(x>=20&&x<=29&&y>=16&&y<=29)){const downtown=x>=21&&x<=29&&y>=16&&y<=29;t.type=h===4?'park':downtown?(h%3===0?'commercial':'office'):(x+y)%7===0?'commercial':'residential';t.density=x>14&&y<30&&h%3!==0?'high':'low';t.level=downtown?1+(x*y)%5:t.density==='high'?2+(x+y)%3:1;t.people=t.type==='residential'?t.level*6:0;t.tree=false;const choices=Object.entries(E.BUILDINGS).filter(([,b])=>b.type===t.type);if(choices.length)t.building=choices[(x+y)%choices.length][0];if(t.type==='residential')t.building=t.density==='low'?'cottage':(x+y)%2?'apartments':'tower';if(t.type==='commercial')t.density=downtown?'high':'low'}}return w}

